using LittleLeo;
using LittleLeo.Events;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "GainBlessingOrEpicDieByDieRewardEventAction", menuName = "Data/BattleSceneSetups/Events/EventActions/GainBlessingOrEpicDieByDieRewardEventAction", order = 0)]
public class GainBlessingOrEpicDieByDieRewardEventAction : GainByDieTierRewardEventAction
{
	[SerializeField]
	private bool starBlessing;

	[SerializeField]
	private BoolActionEvent OnFadeEventsPanelWithAction;

	public override void ExecuteAction(EventButton eventButton)
	{
		EventsPanel eventsPanel = eventButton.EventsPanel;
		eventsPanel.SetComingBackFromFadeAction(delegate
		{
			ReferenceSingleton<GameStateManager>.Instance.SetPlayerRewardStateState();
			eventsPanel.EventButtonPressedUpdateEventDescriptionAndButtons(eventButton.ButtonIndex, instantlyUpdate: true, customEventButtonOnUpdate);
		});
		OnFadeEventsPanelWithAction.Raise(item: false, delegate
		{
			eventsPanel.CleanEventDescriptionAndButtons();
		});
		if (starBlessing)
		{
			eventButton.ToggleBackgroundPurpleForTransitionIgnoreParentGroups(value: true);
			InvokeAlternatives.Invoke(ReferenceSingleton<CoroutineHandler>.Instance, 0.5f, delegate
			{
				eventButton.ToggleBackgroundPurpleForTransitionIgnoreParentGroups(value: false);
			});
		}
		ReferenceSingleton<GameStateManager>.Instance.EndOfBattleState.GoBackToEventsPanelInsteadOfMap = true;
		base.ExecuteAction(eventButton);
	}

	protected override Reward[] GetRewards()
	{
		Reward[] array = new Reward[GetMultiplier()];
		for (int i = 0; i < array.Length; i++)
		{
			array[i] = reward;
		}
		return array;
	}

	public override string GetEventButtonResultText(string resultTextID)
	{
		string text = Smart.Format(ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString(resultTextID), resourceAmount, diceAmount, diceTier.GetLocalizedDiceTierWithDie());
		text = ((!starBlessing) ? (text + "\n" + Smart.Format(ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString("GainEpicDieMultiple"), GetMultiplier() * resourceAmount)) : (text + "\n" + Smart.Format(ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString("GainStarBlessingMultiple"), GetMultiplier() * resourceAmount)));
		if (addDotAtTheEnd)
		{
			text = string.Format(ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedDotAtTheEndFormat(), text);
		}
		return text;
	}
}
